import {css} from "@emotion/react";
import {styled} from "@mui/material/styles";
import {FormControl} from "@mui/material";

interface IFormControl {
  horizontalMargin?: boolean;
  verticalMargin?: boolean;
}

export const MyFormControl = styled(FormControl, {
  shouldForwardProp: (prop) =>
      prop !== "horizontalMargin" &&
      prop !== "verticalMargin",
})<IFormControl>`
  width: 100%;
  min-width: 0;

  ${(props) =>
    props.horizontalMargin === true &&
    css`
      margin-left: 8px;
      margin-right: 8px;
      width: calc(100% - 16px);
    `}

  ${(props) =>
    props.verticalMargin === true &&
    css`
      margin-top: 8px;
      margin-bottom: 8px;
    `}
`;
