import React from "react";
import {Autocomplete, TextField} from "@mui/material";
import {IServiceShort} from "../../../models/service";
import {ProductOptionImage, ProductOptionText, ProductSearchOption} from "./styled";
import {useTranslation} from "../../../i18n";

interface OrderServiceSearchProps {
    options: IServiceShort[];
    inputValue: string;
    isLoading: boolean;
    onInputChange: (value: string) => void;
    onAddService: (service: IServiceShort) => void;
}

const OrderServiceSearch = ({
                                options,
                                inputValue,
                                isLoading,
                                onInputChange,
                                onAddService,
                            }: OrderServiceSearchProps) => {
    const {t} = useTranslation();

    return (
        <Autocomplete
            fullWidth
            value={null}
            loading={isLoading}
            options={options}
            inputValue={inputValue}
            filterOptions={(items) => items}
            getOptionLabel={(option) => option.name}
            noOptionsText={t("Услуги не найдены")}
            loadingText={t("Загрузка услуг...")}
            onInputChange={(_, value, reason) => {
                if (reason === "input" || reason === "clear") {
                    onInputChange(value);
                }
            }}
            onChange={(_, service) => {
                if (service) {
                    onAddService(service);
                }
            }}
            renderOption={(props, option) => (
                <ProductSearchOption {...props} key={option.id}>
                    <ProductOptionImage src={option.imageName || ""} alt={option.name}/>
                    <ProductOptionText>{option.name}</ProductOptionText>
                    <ProductOptionText>{option.price} BYN</ProductOptionText>
                </ProductSearchOption>
            )}
            renderInput={(params) => (
                <TextField
                    {...params}
                    label={t("Поиск услуги")}
                />
            )}
        />
    );
};

export default OrderServiceSearch;
