import React from "react";
import {Autocomplete, Box, Chip, TextField, Typography} from "@mui/material";
import {Link as RouterLink} from "react-router-dom";
import {IShortProduct} from "../../../models/product";
import {
    ProductOptionImage,
    ProductOptionText,
    ProductSearchOption,
} from "./styled";
import {useTranslation} from "../../../i18n";

interface OrderProductSearchProps {
    options: IShortProduct[];
    inputValue: string;
    isLoading: boolean;
    isError?: boolean;
    onInputChange: (value: string) => void;
    onAddProduct: (product: IShortProduct) => void;
}

const OrderProductSearch = ({
                                options,
                                inputValue,
                                isLoading,
                                isError = false,
                                onInputChange,
                                onAddProduct,
                            }: OrderProductSearchProps) => {
    const {t} = useTranslation();

    return (
        <Autocomplete
            fullWidth
            openOnFocus
            autoHighlight
            blurOnSelect={false}
            value={null}
            loading={isLoading}
            options={options}
            inputValue={inputValue}
            filterOptions={(items) => items}
            getOptionLabel={(option) => option.name}
            noOptionsText={isError ? t("Ошибка поиска. Повторите ввод.") : t("Товары не найдены")}
            loadingText={t("Загрузка товаров...")}
            onInputChange={(_, value, reason) => {
                if (reason === "input" || reason === "clear") {
                    onInputChange(value);
                }
            }}
            onChange={(_, product) => {
                if (product) {
                    onAddProduct(product);
                }
            }}
            renderOption={(props, option) => (
                <ProductSearchOption {...props} key={option.id}>
                    <ProductOptionImage src={option.imageName || ""} alt={option.name}/>
                    <Box sx={{minWidth: 0, flex: 1}}><ProductOptionText title={option.name}>{option.name}</ProductOptionText>
                        <Typography variant="caption" color="text.secondary">{option.category}{option.gtin ? ` · GTIN ${option.gtin}` : ''}</Typography>
                        <Box sx={{display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap'}}>
                            <Typography variant="body2" fontWeight={700}>{option.price.toLocaleString('ru-RU', {maximumFractionDigits: 2})} BYN</Typography>
                            {option.count !== undefined && <Chip size="small" variant="outlined" color={option.count > 0 ? 'success' : 'default'} label={option.count > 0 ? `На складе: ${option.count}` : 'Нет на складе'}/>}
                        </Box>
                    </Box>
                    <RouterLink
                        to={`/productDetails/${option.id}`}
                        onClick={(event) => event.stopPropagation()}
                    >
                        {t("Подробнее")}
                    </RouterLink>
                </ProductSearchOption>
            )}
            renderInput={(params) => (
                <TextField
                    {...params}
                    label={t("Поиск товара")}
                    error={isError}
                    helperText={isError ? t("Ошибка поиска. Повторите ввод.") : inputValue.trim() ? t('Уже добавленные товары скрыты. ↑ ↓ — выбрать, Enter — добавить.') : t('Товары доступны сразу: сначала позиции в наличии. Можно искать по названию и GTIN.')}
                />
            )}
        />
    );
};

export default OrderProductSearch;
