import React from "react";
import {FormHelperText, InputLabel, SelectChangeEvent} from "@mui/material";
import {Control, Controller} from "react-hook-form";
import CoreFormControl from "../../../ui/formControl/coreFormControl";
import CoreSelect from "../../../ui/select/coreSelect";
import {
    CreateOrderFormValues,
    DictionaryOption,
    OrderSelectFieldName,
} from "./types";

interface OrderSelectFieldProps {
    control: Control<CreateOrderFormValues>;
    name: OrderSelectFieldName;
    label: string;
    options?: DictionaryOption[];
    error?: string;
    onValueChange: (fieldName: OrderSelectFieldName, value: string) => void;
}

const OrderSelectField = ({
                              control,
                              name,
                              label,
                              options,
                              error,
                              onValueChange,
                          }: OrderSelectFieldProps) => {
    return (
        <Controller
            control={control}
            name={name}
            render={({field}) => (
                <CoreFormControl verticalMargin error={!!error}>
                    <InputLabel id={`${name}-label`}>{label}</InputLabel>
                    <CoreSelect
                        labelId={`${name}-label`}
                        id={name}
                        label={label}
                        value={field.value ?? ""}
                        error={error}
                        menuItemProps={options}
                        onChange={(event: SelectChangeEvent<unknown>) => {
                            const value = String(event.target.value);
                            field.onChange(value);
                            onValueChange(name, value);
                        }}
                    />
                    {error && <FormHelperText>{error}</FormHelperText>}
                </CoreFormControl>
            )}
        />
    );
};

export default OrderSelectField;
