import React, {useEffect, useState} from "react";
import {Box, Button, IconButton, TextField, Typography} from "@mui/material";
import AddCircleIcon from "@mui/icons-material/AddCircle";
import RemoveCircleIcon from "@mui/icons-material/RemoveCircle";
import DeleteIcon from "@mui/icons-material/Delete";
import {IOrderItem} from "../../../models/order";
import {
    ItemMetric,
    QuantityButtonGroup,
    SelectedItemIdentity,
    SelectedItemImage,
    SelectedItemName,
    SelectedItemsList,
    SelectedOrderItemCard,
} from "./styled";
import {useTranslation} from "../../../i18n";

interface SelectedOrderItemsProps {
    items: IOrderItem[];
    onAdd: (item: IOrderItem) => void;
    onRemove: (item: IOrderItem) => void;
    onDelete: (item: IOrderItem) => void;
    onQuantityChange: (item: IOrderItem, count: number) => void;
}

function QuantityField({item, onChange}: {item: IOrderItem; onChange: (item: IOrderItem, count: number) => void}) {
    const [value, setValue] = useState(String(item.count));
    useEffect(() => setValue(String(item.count)), [item.count]);
    const valid = /^\d+(?:[.,]\d{0,6})?$/.test(value) && Number(value.replace(',', '.')) > 0 && Number(value.replace(',', '.')) <= 1e12;
    return <TextField size="small" label="Количество" value={value} sx={{width: 120}} error={!valid}
        inputProps={{inputMode: 'decimal', 'aria-label': `Количество: ${item.name}`}}
        helperText={!valid ? 'Число больше 0, до 6 знаков после запятой' : undefined}
        onChange={event => {const next = event.target.value; setValue(next);
            if (/^\d+(?:[.,]\d{0,6})?$/.test(next)) {const count = Number(next.replace(',', '.')); if (count > 0 && count <= 1e12) onChange(item, count);}}}
        onBlur={() => {if (!valid) setValue(String(item.count));}}
        onKeyDown={event => {if (event.key === 'Enter') {event.preventDefault(); event.currentTarget.querySelector('input')?.blur();}}}/>;
}

const SelectedOrderItems = ({
                                items,
                                onAdd,
                                onRemove,
                                onDelete,
                                onQuantityChange,
                            }: SelectedOrderItemsProps) => {
    const {t} = useTranslation();

    if (items.length === 0) return <Typography color="text.secondary" sx={{py: 3, textAlign: 'center'}}>Состав заказа пока пуст. Выберите товары или услуги выше.</Typography>;

    return (
        <Box><Typography fontWeight={700} sx={{mb: 1}}>В заказе: {items.length} поз. · {items.reduce((sum, item) => sum + item.price * item.count, 0).toLocaleString('ru-RU', {maximumFractionDigits: 2})} BYN</Typography><SelectedItemsList>
            {items.map((item) => (
                <SelectedOrderItemCard key={`${item.itemType}:${item.productId ?? item.serviceId ?? item.id}`}>
                    <SelectedItemIdentity>
                        {item.imageName && (
                            <SelectedItemImage src={item.imageName || ""} alt={item.name}/>
                        )}
                        <SelectedItemName>{item.name}</SelectedItemName>
                    </SelectedItemIdentity>
                    <QuantityButtonGroup>
                        <IconButton
                            disabled={item.count >= 1e12}
                            color="primary"
                            aria-label={t("Увеличить количество: {name}", {name: item.name})}
                            onClick={() => onAdd(item)}
                        >
                            <AddCircleIcon/>
                        </IconButton>
                        <QuantityField item={item} onChange={onQuantityChange}/>
                        <IconButton
                            disabled={item.count <= 1}
                            aria-label={t("Уменьшить количество: {name}", {name: item.name})}
                            onClick={() => onRemove(item)}
                        >
                            <RemoveCircleIcon/>
                        </IconButton>
                    </QuantityButtonGroup>
                    <ItemMetric>{t("Сумма: {sum} BYN", {sum: item.price * item.count})}</ItemMetric>
                    <ItemMetric>{item.price.toLocaleString('ru-RU', {maximumFractionDigits: 2})} BYN / ед.</ItemMetric>
                    <Button
                        color="error"
                        onClick={() => onDelete(item)}
                        startIcon={<DeleteIcon/>}
                    >
                        {t("Удалить")}
                    </Button>
                </SelectedOrderItemCard>
            ))}
        </SelectedItemsList></Box>
    );
};

export default SelectedOrderItems;
