import React from "react";
import {Alert, Autocomplete, Button, Stack, TextField} from "@mui/material";
import {TeamUser, useTeamUsersQuery} from "../../collaboration/collaborationApi";

type Props = {value: number[]; onChange: (value: number[]) => void; disabled?: boolean; existingUsers?: TeamUser[]; error?: string};

export default function OrderResponsibleField({value, onChange, disabled, existingUsers = [], error}: Props) {
    const users = useTeamUsersQuery();
    const current = Array.from(new Set(value || [])).map(id => (users.data || []).find(user => user.id === id) || existingUsers.find(user => user.id === id) || {id, name: `Сотрудник #${id}`});
    const unavailable = current.some(selected => !!users.data && !users.data.some(user => user.id === selected.id));
    const options = [...(users.data || []), ...current.filter(selected => !users.data?.some(user => user.id === selected.id))];
    return <Stack spacing={1} sx={{my: 2}}>
        <Autocomplete multiple filterSelectedOptions disableCloseOnSelect options={options} value={current} disabled={disabled || users.isLoading} loading={users.isFetching}
            clearText="Убрать всех ответственных" closeText="Закрыть" openText="Выбрать сотрудников"
            isOptionEqualToValue={(a,b) => a.id === b.id} getOptionLabel={user => user.name} getOptionDisabled={user => !!users.data && !users.data.some(available => available.id === user.id)}
            onChange={(_,selected) => onChange(selected.map(user => user.id))} noOptionsText={users.isError ? "Сотрудники недоступны" : "Сотрудники не найдены"} loadingText="Загружаем сотрудников…"
            renderInput={input => <TextField {...input} error={!!error || unavailable} label="Ответственные за заказ" helperText={error || (unavailable ? "Один из сотрудников больше недоступен. Уберите его из выбранных ответственных." : "Обязательно выберите сотрудника или администратора этой компании. Можно назначить нескольких человек.")}/>}/>
        {users.isError && <Alert severity="error">Не удалось загрузить сотрудников. <Button onClick={() => void users.refetch()}>Повторить загрузку сотрудников</Button></Alert>}
    </Stack>;
}
