import QueryError from "../../shared/QueryError";
import React, {useEffect, useMemo, useState} from "react";
import {NavLink, useLocation, useNavigate, useParams} from "react-router-dom";
import {Controller, useForm, useWatch} from "react-hook-form";
import {yupResolver} from "@hookform/resolvers/yup";
import useFormPersist from "react-hook-form-persist";
import {toast} from "react-toastify";
import CategoryOutlinedIcon from "@mui/icons-material/CategoryOutlined";
import {useGetDeliveryMethodsQuery} from "../../shared/deliveryMethod/deliveryMethodsApi";
import {useGetPaymentMethodsQuery} from "../../shared/paymentMethod/paymentMethodsApi";
import {useGetSourcesQuery} from "../../shared/sources/sourceApi";
import {
    useCreateOrderMutation,
    useEditOrderMutation,
    useGetOrderByIdQuery,
    useGetOrderProductOptionsQuery,
    useGetOrderServiceOptionsQuery,
} from "./createOrderApi";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
} from "../../../ui/commonStyled/commonStyled";
import CoreButton from "../../../ui/buttons/coreButton";
import {getApiErrorMessage} from "../../../api/errors";
import Loader from "../../../ui/loader/loader";
import {formatPhoneNumber} from "../../../hooks/formatPhoneNumber";
import useDebounce from "../../../hooks/useDebounce";
import {ICreateOrEditOrder, IOrderItem, OrderItemType} from "../../../models/order";
import {IShortProduct} from "../../../models/product";
import {IServiceShort} from "../../../models/service";
import {createOrderSchema} from "./createOrderSchema";
import OrderProductSearch from "./OrderProductSearch";
import OrderServiceSearch from "./OrderServiceSearch";
import SelectedOrderItems from "./SelectedOrderItems";
import OrderSelectField from "./OrderSelectField";
import OrderResponsibleField from "./OrderResponsibleField";
import OrderCustomerFields from "./OrderCustomerFields";
import OrderAdditionalFields from "./OrderAdditionalFields";
import {CreateOrderFormValues, OrderSelectFieldName} from "./types";
import {clearCreateOrderDraft, getOrderDraftStorageKey} from "./createOrderDraft";
import {ICustomerCard} from "../../../models/customer";
import {
    CreateOrderLayout,
    FormSectionTitle,
    OrderForm,
    PanelHeading,
    PanelText,
    PanelTitle,
    ProductSearchPanel,
} from "./styled";
import {useTranslation} from "../../../i18n";

const defaultValues: CreateOrderFormValues = {
    customer: {
        name: "",
        address: "",
        phone: "+375",
    },
    deliveryMethodId: "",
    sourceId: "",
    responsibleUserId: null,
    responsibleUserIds: [],
    paymentMethodId: "",
    orderItems: [],
    discount: 0,
};

const getOrderItemKey = (item: IOrderItem) => {
    const itemId = item.itemType === OrderItemType.Service
        ? item.serviceId ?? item.id
        : item.productId ?? item.id;

    return `${item.itemType}:${itemId}`;
};

const normalizeOrderItem = (item: IOrderItem): IOrderItem => ({
    ...item,
    itemType: item.itemType ?? OrderItemType.Product,
    productId: item.productId ?? (item.itemType === OrderItemType.Product ? item.id : null),
    serviceId: item.serviceId ?? (item.itemType === OrderItemType.Service ? item.id : null),
    name: item.itemName || item.product || item.name,
    imageName: item.imageName || null,
});

const toProductOrderItem = (product: IShortProduct): IOrderItem => ({
    id: product.id,
    itemType: OrderItemType.Product,
    productId: product.id,
    serviceId: null,
    name: product.name,
    imageName: product.imageName || null,
    price: product.price,
    count: 1,
    sum: 0,
});

const toServiceOrderItem = (service: IServiceShort): IOrderItem => ({
    id: service.id,
    itemType: OrderItemType.Service,
    productId: null,
    serviceId: service.id,
    name: service.name,
    imageName: service.imageName || null,
    price: service.price,
    count: 1,
    sum: 0,
});

const CreateOrder = () => {
    const {id} = useParams<{ id: string }>();
    const navigate = useNavigate();
    const location = useLocation();
    const {t} = useTranslation();
    const validationSchema = useMemo(() => createOrderSchema(t), [t]);

    const {data: deliveryMethods, isLoading: isDeliveryMethodsLoading, isError: isDeliveryMethodsError, error: deliveryMethodsError, refetch: refetchDeliveryMethods} = useGetDeliveryMethodsQuery({});
    const {data: paymentMethods, isLoading: isPaymentMethodsLoading, isError: isPaymentMethodsError, error: paymentMethodsError, refetch: refetchPaymentMethods} = useGetPaymentMethodsQuery({});
    const {data: sources, isLoading: isSourcesLoading, isError: isSourcesError, error: sourcesError, refetch: refetchSources} = useGetSourcesQuery({});
    const {data: order, isLoading: isOrderLoading, isError: isOrderError, error: orderError, refetch: refetchOrder} = useGetOrderByIdQuery(id!, {skip: !id});

    const [createOrder, {isLoading: isCreatingOrder}] = useCreateOrderMutation();
    const [editOrder, {isLoading: isEditingOrder}] = useEditOrderMutation();

    const [searchTerm, setSearchTerm] = useState("");
    const [serviceSearchTerm, setServiceSearchTerm] = useState("");
    const debouncedSearchTerm = useDebounce(searchTerm.trim(), 250);
    const debouncedServiceSearchTerm = useDebounce(serviceSearchTerm.trim(), 500);
    const {
        data: serviceOptions = [],
        isFetching: isServiceOptionsFetching,
    } = useGetOrderServiceOptionsQuery(debouncedServiceSearchTerm, {
        skip: debouncedServiceSearchTerm.length === 0,
    });

    const {
        watch,
        control,
        clearErrors,
        setValue,
        register,
        reset,
        handleSubmit,
        getValues,
        formState: {errors},
    } = useForm<CreateOrderFormValues>({
        resolver: yupResolver(validationSchema),
        defaultValues,
    });

    const orderItems = useWatch({control, name: "orderItems"}) ?? [];
    const excludedProductIds = orderItems.filter(item => item.itemType === OrderItemType.Product).map(item => item.productId ?? item.id);
    const {
        currentData: productOptions = [],
        isFetching: isProductOptionsFetching,
        isError: isProductOptionsError,
    } = useGetOrderProductOptionsQuery({searchTerm: debouncedSearchTerm, excludedIds: excludedProductIds.join(',')});
    const isSaving = isCreatingOrder || isEditingOrder;

    const {clear: clearPersistedOrderDraft} = useFormPersist(getOrderDraftStorageKey(id), {
        watch,
        setValue,
        storage: window.localStorage,
    });

    useEffect(() => {
        if (id) return;
        const legacyId = getValues("responsibleUserId");
        if (legacyId && !getValues("responsibleUserIds")?.length) setValue("responsibleUserIds", [legacyId]);
        setValue("responsibleUserId", null);
    }, [id, getValues, setValue]);

    useEffect(() => {
        if (!order) {
            return;
        }

        setValue("customer.name", order.customer.name);
        setValue("customer.id", order.customer.id ?? null);
        setValue("customer.address", order.customer.address);
        setValue("customer.phone", order.customer.phone);
        setValue('customer.organization', order.customer.organization || null);
        setValue("sourceId", String(order.sourceId ?? ""));
        setValue("responsibleUserIds", order.responsibleUserIds ?? order.responsibleUsers?.map(user => user.id) ?? (order.responsibleUserId ? [order.responsibleUserId] : []));
        setValue("responsibleUserId", null);
        setValue("deliveryMethodId", String(order.deliveryMethodId ?? ""));
        setValue("paymentMethodId", String(order.paymentMethodId ?? ""));
        setValue("discount", order.discount ?? 0);
        setValue("comment", order.comment ?? undefined);
        setValue("orderItems", (order.orderItems ?? []).map(normalizeOrderItem));
    }, [order, setValue]);

    useEffect(() => {
        const customer = (location.state as {customer?: ICustomerCard} | null)?.customer;
        if (id || !customer) return;
        setValue('customer', {id: customer.id, name: customer.name, address: customer.address,
            phone: /^\+?375/.test(customer.phone) ? formatPhoneNumber(customer.phone) : customer.phone}, {shouldDirty: true});
    }, [id, location.state, setValue]);

    const setOrderItems = (items: IOrderItem[]) => {
        setValue("orderItems", items, {
            shouldDirty: true,
            shouldValidate: true,
        });
    };

    const handlePhoneChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const input = event.target.value;
        const formattedValue = /^\+?375/.test(input) ? formatPhoneNumber(input) : input;

        if (formattedValue.length <= 64) {
            setValue("customer.phone", formattedValue, {
                shouldDirty: true,
                shouldValidate: true,
            });
        }
    };

    const handleSelectFieldChange = (
        fieldName: OrderSelectFieldName,
        value: string,
    ) => {
        setValue(fieldName, value, {
            shouldDirty: true,
            shouldValidate: true,
        });

        if (value) {
            clearErrors(fieldName);
        }
    };

    const handleAddOrderItem = (nextItem: IOrderItem) => {
        const currentOrderItems = getValues("orderItems") ?? [];
        const nextItemKey = getOrderItemKey(nextItem);
        const productIndex = currentOrderItems.findIndex((item) => getOrderItemKey(normalizeOrderItem(item)) === nextItemKey);

        const nextOrderItems =
            productIndex >= 0
                ? currentOrderItems.map((item, index) =>
                    index === productIndex ? {...item, count: Math.min(1e12, Math.round((item.count + 1) * 1e6) / 1e6)} : item,
                )
                : [...currentOrderItems, nextItem];

        setOrderItems(nextOrderItems);
        clearErrors("orderItems");
    };

    const handleAddProduct = (product: IShortProduct) => {
        handleAddOrderItem(toProductOrderItem(product));
        setSearchTerm('');
    };

    const handleAddService = (service: IServiceShort) => {
        handleAddOrderItem(toServiceOrderItem(service));
    };

    const handleRemoveOrderItem = (orderItem: IOrderItem) => {
        const currentOrderItems = getValues("orderItems") ?? [];
        const removedItemKey = getOrderItemKey(normalizeOrderItem(orderItem));
        const nextOrderItems = currentOrderItems
            .map((item) =>
                getOrderItemKey(normalizeOrderItem(item)) === removedItemKey ? {...item, count: item.count - 1} : item,
            )
            .filter((item) => item.count > 0);

        setOrderItems(nextOrderItems);
    };

    const handleDeleteOrderItem = (orderItem: IOrderItem) => {
        const currentOrderItems = getValues("orderItems") ?? [];
        const deletedItemKey = getOrderItemKey(normalizeOrderItem(orderItem));
        setOrderItems(currentOrderItems.filter((item) => getOrderItemKey(normalizeOrderItem(item)) !== deletedItemKey));
    };

    const handleQuantityChange = (orderItem: IOrderItem, count: number) => {
        const key = getOrderItemKey(normalizeOrderItem(orderItem));
        setOrderItems((getValues('orderItems') ?? []).map(item => getOrderItemKey(normalizeOrderItem(item)) === key ? {...item, count} : item));
    };

    const createOrderHandler = async (values: CreateOrderFormValues) => {
        if (values.orderItems.length === 0) {
            toast.error(t("Добавьте хотя бы один товар в заказ"));
            return;
        }

        const orderPayload: ICreateOrEditOrder = {
            customer: values.customer,
            deliveryMethodId: values.deliveryMethodId,
            sourceId: values.sourceId,
            responsibleUserIds: values.responsibleUserIds,
            responsibleUserId: values.responsibleUserIds[0] ?? null,
            paymentMethodId: values.paymentMethodId,
            comment: values.comment,
            discount: values.discount,
            orderItems: values.orderItems.map((item) => ({
                itemType: item.itemType,
                productId: item.itemType === OrderItemType.Product ? item.productId ?? item.id : null,
                serviceId: item.itemType === OrderItemType.Service ? item.serviceId ?? item.id : null,
                count: item.count,
            })),
        };

        try {
            if (id) {
                await editOrder({...orderPayload, id}).unwrap();
                toast.success(t("Order was changed"));
            } else {
                await createOrder(orderPayload).unwrap();
                toast.success(t("Order was created"));
            }

            reset(defaultValues);
            clearPersistedOrderDraft();
            clearCreateOrderDraft(id);
            navigate("/ordersManagement", {replace: true});
        } catch (error) {
            toast.error(getApiErrorMessage(error, t("Order was not saved")));
        }
    };

    if (
        isDeliveryMethodsLoading ||
        isPaymentMethodsLoading ||
        isSourcesLoading ||
        isOrderLoading
    ) {
        return <Loader/>;
    }

    if (id && (isOrderError || !order)) return <MainDiv><QueryError error={orderError} onRetry={refetchOrder}/></MainDiv>;
    if (isDeliveryMethodsError) return <MainDiv><QueryError error={deliveryMethodsError} onRetry={refetchDeliveryMethods}/></MainDiv>;
    if (isPaymentMethodsError) return <MainDiv><QueryError error={paymentMethodsError} onRetry={refetchPaymentMethods}/></MainDiv>;
    if (isSourcesError) return <MainDiv><QueryError error={sourcesError} onRetry={refetchSources}/></MainDiv>;

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{id ? t("Редактирование заказа") : t("Новый заказ")}</PageTitle>
                    <PageSubtitle>
                        {t("Соберите товары, данные клиента, доставку и оплату в одном быстром потоке.")}
                    </PageSubtitle>
                </PageTitleGroup>
                <NavLink replace to="categories" style={{textDecoration: "none"}}>
                    <CoreButton
                        muiType="info"
                        leftIcon={<CategoryOutlinedIcon/>}
                        text={t("Каталог категорий")}
                    />
                </NavLink>
            </PageHeader>

            <CreateOrderLayout>
                <ProductSearchPanel>
                    <PanelTitle>
                        <PanelHeading>{t("Товары в заказе")}</PanelHeading>
                        <PanelText>{t("Выберите товар из списка или найдите по названию, описанию и GTIN. Количество меняется в составе заказа.")}</PanelText>
                    </PanelTitle>
                    <OrderProductSearch
                        options={debouncedSearchTerm === searchTerm.trim() ? productOptions.filter(item => !excludedProductIds.includes(item.id)) : []}
                        inputValue={searchTerm}
                        isLoading={isProductOptionsFetching || debouncedSearchTerm !== searchTerm.trim()}
                        isError={isProductOptionsError}
                        onInputChange={setSearchTerm}
                        onAddProduct={handleAddProduct}
                    />
                    <OrderServiceSearch
                        options={serviceOptions}
                        inputValue={serviceSearchTerm}
                        isLoading={isServiceOptionsFetching}
                        onInputChange={setServiceSearchTerm}
                        onAddService={handleAddService}
                    />
                    <SelectedOrderItems
                        items={orderItems}
                        onAdd={handleAddOrderItem}
                        onRemove={handleRemoveOrderItem}
                        onDelete={handleDeleteOrderItem}
                        onQuantityChange={handleQuantityChange}
                    />
                </ProductSearchPanel>

                <OrderForm onSubmit={handleSubmit(createOrderHandler)}>
                    <FormSectionTitle>{t("Данные заказа")}</FormSectionTitle>
                    <OrderCustomerFields
                        control={control}
                        setValue={setValue}
                        register={register}
                        errors={errors}
                        onPhoneChange={handlePhoneChange}
                        initialCustomer={(location.state as {customer?: ICustomerCard} | null)?.customer}
                    />
                    <OrderSelectField
                        control={control}
                        name="deliveryMethodId"
                        label={t("Способ доставки")}
                        options={deliveryMethods}
                        error={errors.deliveryMethodId?.message}
                        onValueChange={handleSelectFieldChange}
                    />
                    <OrderSelectField
                        control={control}
                        name="sourceId"
                        label={t("Источник")}
                        options={sources}
                        error={errors.sourceId?.message}
                        onValueChange={handleSelectFieldChange}
                    />
                    <OrderSelectField
                        control={control}
                        name="paymentMethodId"
                        label={t("Способ оплаты")}
                        options={paymentMethods}
                        error={errors.paymentMethodId?.message}
                        onValueChange={handleSelectFieldChange}
                    />
                    <OrderAdditionalFields
                        register={register}
                        errors={errors}
                    />
                    <Controller control={control} name="responsibleUserIds" render={({field}) => <OrderResponsibleField
                        value={field.value ?? []} onChange={field.onChange} disabled={isSaving} error={errors.responsibleUserIds?.message}
                        existingUsers={order?.responsibleUsers ?? (order?.responsibleUserId ? [{id:order.responsibleUserId,name:order.responsibleUserName || `Сотрудник #${order.responsibleUserId}`}] : [])}/>}/>
                    <CoreButton
                        type="submit"
                        muiType="success"
                        fullWidth
                        disabled={isSaving}
                        text={isSaving ? t("Сохранение...") : t("Сохранить заказ")}
                    />
                </OrderForm>
            </CreateOrderLayout>
        </MainDiv>
    );
};

export default CreateOrder;
