import React, {useState} from "react";
import {Alert, Autocomplete, Box, Button, Dialog, DialogContent, DialogTitle, MenuItem, Stack, TextField, Typography} from "@mui/material";
import CompanyPicker from '../../counterparties/CompanyPicker';
import {companyIdentity} from '../../counterparties/counterpartiesApi';
import {Control, FieldErrors, UseFormRegister, UseFormSetValue, useWatch} from "react-hook-form";
import CoreTextField from "../../../ui/textFields/coreTextField";
import {CreateOrderFormValues} from "./types";
import {PhoneFieldWrap} from "./styled";
import {useTranslation} from "../../../i18n";
import {useGetOrderCustomersQuery} from "./createOrderApi";
import useDebounce from "../../../hooks/useDebounce";
import {customerPhoneKey, ICustomerCard} from "../../../models/customer";
import OrderCustomerInsight from './OrderCustomerInsight';
import {formatPhoneNumber} from "../../../hooks/formatPhoneNumber";

interface Props {
    control: Control<CreateOrderFormValues>;
    setValue: UseFormSetValue<CreateOrderFormValues>;
    register: UseFormRegister<CreateOrderFormValues>;
    errors: FieldErrors<CreateOrderFormValues>;
    onPhoneChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
    initialCustomer?: ICustomerCard;
}

export default function OrderCustomerFields({control, setValue, register, errors, onPhoneChange, initialCustomer}: Props) {
    const {t} = useTranslation();
    const customer = useWatch({control, name: 'customer'});
    const [open, setOpen] = useState(false);
    const [companyOpen, setCompanyOpen] = useState(false);
    const [selected, setSelected] = useState<ICustomerCard | null>(initialCustomer || null);
    const search = useDebounce(customer?.name?.trim() || '', 300);
    const phoneSearch = useDebounce(customer?.phone || '', 400);
    const {currentData: matches, isFetching, isError} = useGetOrderCustomersQuery({search, pageSize: 8}, {skip: !open});
    const {currentData: samePhone} = useGetOrderCustomersQuery({phone: phoneSearch, pageSize: 8}, {
        skip: !!customer?.id || customerPhoneKey(phoneSearch).length < 7,
    });
    const phoneMatches = samePhone?.items.filter(item => [item.phone, ...(item.phones?.map(p => p.phone) || [])].some(phone => customerPhoneKey(phone) === customerPhoneKey(customer?.phone || ''))) || [];
    function select(item: ICustomerCard, keepPhone = false) {
        const phone = keepPhone ? customer?.phone || item.phone : item.phone;
        setSelected(item);
        setValue('customer.organization', null, {shouldDirty: true});
        setValue('customer.id', item.id, {shouldDirty: true});
        setValue('customer.name', item.name, {shouldDirty: true, shouldValidate: true});
        setValue('customer.address', item.address, {shouldDirty: true, shouldValidate: true});
        setValue('customer.phone', /^\+?375/.test(phone) ? formatPhoneNumber(phone) : phone, {shouldDirty: true, shouldValidate: true});
        setOpen(false);
    }
    return <>
        <Box sx={{gridColumn: '1 / -1'}}>
            <Button type="button" variant="outlined" onClick={() => setCompanyOpen(true)}>Найти организацию по ИНН / УНП / БИН</Button>
            {customer?.organization && <Alert severity="info" sx={{mt: 1}} action={<Button type="button" onClick={() => setValue('customer.organization', null, {shouldDirty: true, shouldValidate: true})}>Убрать</Button>}>
                {customer.organization.country} · {customer.organization.taxNumber}{customer.organization.kpp ? ` · КПП ${customer.organization.kpp}` : ''}. Реквизиты будут сохранены с заказом.
            </Alert>}
        </Box>
        <Dialog open={companyOpen} onClose={() => setCompanyOpen(false)} fullWidth maxWidth="md"><DialogTitle>Поиск и проверка организации</DialogTitle><DialogContent sx={{pt: '12px !important'}}>
            <CompanyPicker initialQuery={customer?.organization?.taxNumber || ''} initialCountry={customer?.organization?.country} onSelect={company => {
                setValue('customer.id', null, {shouldDirty: true}); setSelected(null);
                setValue('customer.organization', companyIdentity(company), {shouldDirty: true});
                setValue('customer.name', company.name, {shouldDirty: true, shouldValidate: true});
                setValue('customer.address', company.address, {shouldDirty: true, shouldValidate: true});
                if (company.phone) setValue('customer.phone', company.phone, {shouldDirty: true, shouldValidate: true});
                setCompanyOpen(false);
            }}/><Button type="button" onClick={() => setCompanyOpen(false)} sx={{mt: 2}}>Закрыть</Button>
        </DialogContent></Dialog>
        <Autocomplete<ICustomerCard, false, false, true> freeSolo open={open} value={null} inputValue={customer?.name || ''}
            onOpen={() => setOpen(true)} onClose={() => setOpen(false)} autoSelect={false} autoHighlight={false} clearOnBlur={false}
            options={matches?.items || []} loading={isFetching} filterOptions={items => items}
            getOptionLabel={item => typeof item === 'string' ? item : item.name}
            onInputChange={(_, value, reason) => {if (reason === 'input' || reason === 'clear') {
                setValue('customer.id', null, {shouldDirty: true});
                setValue('customer.name', value, {shouldDirty: true});
            }}}
            onChange={(_, item) => {if (item && typeof item !== 'string') select(item);}}
            renderOption={(props, item) => <li {...props} key={item.id}><Box>
                <Typography fontWeight={700}>{item.name}</Typography>
                <Typography variant="body2" color="text.secondary">{item.phone} · Заказов: {item.orderCount}</Typography>
                <Typography variant="caption" color="text.secondary">{item.address}</Typography>
            </Box></li>}
            renderInput={params => <TextField {...params} label={t('Ф.И.О. контрагента')} error={!!errors.customer?.name}
                helperText={errors.customer?.name?.message || (isError ? 'Не удалось загрузить подсказки. Можно заполнить данные вручную.' : 'Начните вводить имя или телефон и выберите клиента из прошлых заказов.')}/>} />
        <CoreTextField label={t('Адрес')} register={register} name="customer.address" error={errors.customer?.address?.message} verticalMargin/>
        <PhoneFieldWrap><TextField fullWidth label={t('Телефон')} {...register('customer.phone', {onChange: onPhoneChange})}
            error={!!errors.customer?.phone} helperText={errors.customer?.phone?.message}/></PhoneFieldWrap>
        <Box sx={{gridColumn: '1 / -1'}}>
            {customer?.id && <Stack spacing={1}>
                <Typography variant="body2" color="text.secondary">Выбран клиент из базы. Адрес и телефон можно изменить для этого заказа. Новый телефон добавится в карточку при сохранении.</Typography>
                {selected?.id === customer.id && selected.phones && selected.phones.length > 1 && <TextField select size="small" label="Номер для связи по заказу" value={selected.phones.some(p => customerPhoneKey(p.phone) === customerPhoneKey(customer.phone)) ? selected.phones.find(p => customerPhoneKey(p.phone) === customerPhoneKey(customer.phone))!.phone : ''}
                    onChange={event => setValue('customer.phone', event.target.value, {shouldDirty: true, shouldValidate: true})}>
                    <MenuItem value="">Другой номер — введите выше</MenuItem>{selected.phones.map(phone => <MenuItem key={phone.phone} value={phone.phone}>{phone.phone}{phone.label ? ` · ${phone.label}` : ''}</MenuItem>)}
                </TextField>}
                <OrderCustomerInsight customerId={customer.id}/>
                <Button sx={{alignSelf: 'flex-start'}} onClick={() => {setValue('customer.id', null, {shouldDirty: true}); setSelected(null);}}>Это другой клиент — отвязать карточку</Button>
            </Stack>}
            {phoneMatches.length > 0 && !customer?.id && <Alert severity="info">
                Такой телефон уже есть в базе. Выберите клиента, если это тот же человек; для другого клиента оставьте введённое имя.
                <Box sx={{display: 'flex', flexWrap: 'wrap', gap: 1, mt: 1}}>{phoneMatches.map(item => <Button key={item.id} type="button" variant="outlined" onClick={() => select(item, true)}>
                    {item.name} · заказов: {item.orderCount}
                </Button>)}</Box>
            </Alert>}
        </Box>
    </>;
}
