import {Alert, Button, Chip, Stack, Typography} from '@mui/material';
import {Link} from 'react-router-dom';
import {communicationStyles} from '../../../models/customer';
import {useGetCustomerQuery} from './createOrderApi';

export default function OrderCustomerInsight({customerId}: {customerId: number}) {
    const {currentData: customer, isError} = useGetCustomerQuery(customerId);
    return <Stack spacing={1}>
        {isError && <Typography variant="body2" color="text.secondary">Памятка клиента временно недоступна.</Typography>}
        {customer && <>
            <Stack direction="row" gap={1} flexWrap="wrap">
                {customer.communicationStyle !== 'unknown' && <Chip size="small" label={communicationStyles[customer.communicationStyle] || 'Стиль общения не указан'}/>}
                {customer.attentionRequired && <Chip size="small" color="warning" label="Требует внимания"/>}
                {customer.openIncidentCount > 0 && <Chip size="small" color="warning" label={`Открытых ситуаций: ${customer.openIncidentCount}`}/>}
            </Stack>
            {customer.summary && <Alert severity={customer.attentionRequired ? 'warning' : 'info'} sx={{whiteSpace: 'pre-wrap'}}>{customer.summary}</Alert>}
        </>}
        <Button component={Link} to={`/customers?customer=${customerId}`} sx={{alignSelf: 'flex-start'}}>Карточка клиента, история и заметки</Button>
    </Stack>;
}
