import * as Yup from "yup";
import {IOrderItem} from "../../../models/order";
import {Translate} from "../../../i18n";

export const createOrderSchema = (t: Translate) => Yup.object().shape({
    customer: Yup.object().shape({
        organization: Yup.object().shape({country: Yup.string().oneOf(['RU','BY','KZ']).required(), taxNumber: Yup.string().required(), kpp: Yup.string().nullable().optional()}).nullable().default(undefined).optional(),
        id: Yup.number().nullable().positive().integer().optional(),
        name: Yup.string()
            .min(2, t("Слишком короткое имя"))
            .max(200, t("Слишком длинное имя"))
            .required(t("Введите Ф.И.О. контрагента")),
        address: Yup.string()
            .min(2, t("Слишком короткий адрес"))
            .max(1000, t("Слишком длинный адрес"))
            .required(t("Введите адрес контрагента")),
        phone: Yup.string().defined().when('organization', {
            is: (value: unknown) => !!value,
            then: schema => schema.test('company-phone', t("Невалидный номер телефона"), value => !value || (/^[+0-9\s()-]+$/.test(value) && value.replace(/[^0-9]/g, '').length >= 7 && value.replace(/[^0-9]/g, '').length <= 20)),
            otherwise: schema => schema
            .test('phone', t("Невалидный номер телефона"), value => !!value && /^[+0-9\s()-]+$/.test(value) && value.replace(/[^0-9]/g, '').length >= 7 && value.replace(/[^0-9]/g, '').length <= 20)
            .required(t("Введите номер телефона")),
        }),
    }),
    paymentMethodId: Yup.string().required(t("Выберите способ оплаты")),
    deliveryMethodId: Yup.string().required(t("Выберите способ доставки")),
    sourceId: Yup.string().required(t("Выберите источник заказа")),
    responsibleUserId: Yup.number().nullable().integer().positive().optional(),
    responsibleUserIds: Yup.array().of(Yup.number().integer().positive().required())
        .min(1, "Выберите хотя бы одного ответственного сотрудника компании.").required(),
    comment: Yup.string(),
    discount: Yup.number().required(),
    orderItems: Yup.array<IOrderItem>().required(),
});
