export const formatPhoneNumber = (input: string) => {
    input = input.replace(/\D/g, '');
    let formattedNumber = '+375';

    if (input.length >= 3) {
        formattedNumber += ' (' + input.substr(3, 2);
    }
    if (input.length > 5) {
        formattedNumber += ') ' + input.substr(5, 2);
    }
    if (input.length >= 8) {
        formattedNumber += '-' + input.substr(7, 3);
    }
    if (input.length >= 11 && input.length <= 19) {
        formattedNumber += '-' + input.substr(10);
    }
    return formattedNumber;
};
