import React from "react";
import {FieldErrors, UseFormRegister} from "react-hook-form";
import CoreTextField from "../../../ui/textFields/coreTextField";
import {CreateOrderFormValues} from "./types";
import {useTranslation} from "../../../i18n";

interface OrderAdditionalFieldsProps {
    register: UseFormRegister<CreateOrderFormValues>;
    errors: FieldErrors<CreateOrderFormValues>;
}

const OrderAdditionalFields = ({
                                   register,
                                   errors,
                               }: OrderAdditionalFieldsProps) => {
    const {t} = useTranslation();

    return (
        <>
            <CoreTextField
                label={t("Комментарий")}
                register={register}
                name="comment"
                error={errors.comment?.message}
                verticalMargin
            />
            <CoreTextField
                type="number"
                label={t("Скидка, %")}
                register={register}
                name="discount"
                error={errors.discount?.message}
                verticalMargin
            />
        </>
    );
};

export default OrderAdditionalFields;
